"""Data processing runner for mini_harness."""

from __future__ import annotations

import csv
import json
from pathlib import Path
from typing import Iterable


class HarnessError(Exception):
    """Raised when harness processing fails."""


def _record_has_id(record: dict) -> bool:
    for key, value in record.items():
        if str(key).lower() == "id":
            return value is not None and str(value).strip() != ""
    return False


def _iter_csv(path: Path) -> Iterable[dict]:
    with path.open("r", encoding="utf-8-sig", newline="") as handle:
        reader = csv.DictReader(handle)
        for row in reader:
            if row and any(value not in (None, "") for value in row.values()):
                yield row


def _iter_jsonl(path: Path) -> Iterable[dict]:
    with path.open("r", encoding="utf-8-sig") as handle:
        for line_number, line in enumerate(handle, start=1):
            text = line.strip()
            if not text:
                continue
            try:
                value = json.loads(text)
            except json.JSONDecodeError as exc:
                raise HarnessError(f"Invalid JSONL in {path} line {line_number}: {exc}") from exc
            if not isinstance(value, dict):
                raise HarnessError(f"JSONL record in {path} line {line_number} is not an object")
            yield value


def _iter_records(path: Path) -> Iterable[dict]:
    suffix = path.suffix.lower()
    if suffix == ".csv":
        return _iter_csv(path)
    if suffix == ".jsonl":
        return _iter_jsonl(path)
    raise HarnessError(f"Unsupported input file type: {path}")


def run_dag(input_files: Iterable[str], output: str | None = None) -> dict:
    """Process CSV/JSONL inputs and optionally write the JSON report."""

    source_files = [str(item) for item in input_files]
    processed_count = 0
    rejected_count = 0

    for source in source_files:
        path = Path(source)
        if not path.exists():
            raise HarnessError(f"Input file not found: {source}")
        try:
            for record in _iter_records(path):
                if _record_has_id(record):
                    processed_count += 1
                else:
                    rejected_count += 1
        except OSError as exc:
            raise HarnessError(f"Failed to read {source}: {exc}") from exc

    report = {
        "processed_count": processed_count,
        "rejected_count": rejected_count,
        "retry_count": 0,
        "source_files": source_files,
    }

    if output is not None:
        output_path = Path(output)
        try:
            output_path.parent.mkdir(parents=True, exist_ok=True)
            output_path.write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        except OSError as exc:
            raise HarnessError(f"Failed to write report {output}: {exc}") from exc

    return report

